    artifactBlob(artifact.id, controller.signal).then((blob) => {
      if (!controller.signal.aborted) {
        url = URL.createObjectURL(blob)
        setPreview(url)

async function download() {
  setBusy(true)
  setError('')
  let url = ''
  try {
    url = preview || URL.createObjectURL(await artifactBlob(artifact.id))
    const link = document.createElement('a')
    link.href = url
    link.download = artifact.filename
    document.body.appendChild(link)
    link.click()
    link.remove()
    // 延迟释放，让浏览器有机会开始下载；预览地址由 effect 管理。
    if (!preview) { const downloadUrl = url; window.setTimeout(() => URL.revokeObjectURL(downloadUrl), 1000) }

async function fetchResponse(url: string, options: RequestInit): Promise<Response> {
  try {
    return await fetch(url, options)
  } catch (cause) {
    // 浏览器的网络异常未经过后端，统一转换成中文；主动取消请求保留原异常。
    if (!options.signal?.aborted && cause instanceof TypeError) {
      throw new Error('无法连接服务，请确认前后端已启动并检查网络。')
    }
    throw cause
  }

} catch (cause) {
  if (!controller.signal.aborted) {
    setError(cause instanceof Error ? cause.message : '发送失败')
    if (!answerFinalized) {
      setMessages((items) => items.at(-1)?.role === 'assistant'
        ? items.map((item, index) => index === items.length - 1
          ? { ...item, content: '本次回答未完成，生成或核对失败，请重试。', sources: [], sourcesPending: false }
          : item)
        : items)
    }
  }
} finally {
  activeRequest.current = null
  setBusy(false)
